function fibonacci(n) {
  if (n <= 1) return n;
  
  const memo = new Map();
  const fib = (x) => {
    if (memo.has(x)) return memo.get(x);
    const result = fib(x - 1) + fib(x - 2);
    memo.set(x, result);
    return result;
  };
  
  return fib(n);
}

